pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // Assume newOwner is not the zero address (standard sensible constraint)
        vm.assume(newOwner != address(0));
        // Assume newOwner is not the current owner, otherwise both versions behave identically
        vm.assume(newOwner != c.owner());
        // The current caller must be the owner to satisfy the onlyOwner modifier
        vm.prank(c.owner());
        c.transferOwnership(newOwner);
        // After the call, the reference contract (C_reference) owner becomes newOwner,
        // while the mutant (C_buggy) remains as the original owner.
        // This assertion will only fail for the buggy version when newOwner != original owner.
        assertTrue(c.owner() == newOwner);
    }
}

