import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Anyone other than owner should fail on reference, succeed on buggy.
        vm.assume(caller != c.owner());

        vm.prank(caller);
        bool ok = true;
        try c.owned() {} catch { ok = false; }

        // On reference: ok == false (caller is not owner). On buggy: ok == true.
        // The universal rule reference satisfies: For any caller != owner, owned() reverts.
        assertTrue(!ok);
    }
}

